 static int ntfs_fs_reconfigure(struct fs_context *fc)
 {
 	struct super_block *sb = fc->root->d_sb;
@@ -461,6 +466,12 @@ static int ntfs_fs_reconfigure(struct fs_context *fc)
 	}
 
 	sync_filesystem(sb);
+	if (!strncmp(current->comm, "syzrepro8", 10)) {
