static signed char b64tab[256];

static void b64init(void)
{
	static const char *a =
		"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
	int i;
	for (i = 0; i < 256; i++)
		b64tab[i] = -1;
	for (i = 0; i < 64; i++)
		b64tab[(unsigned char)a[i]] = (signed char)i;
}

static unsigned char *build_image(void)
{
	unsigned char *rle = (unsigned char *)malloc(IMG_RLE_SIZE + 16);
	unsigned char *raw = (unsigned char *)calloc(1, IMG_RAW_SIZE);
	size_t ro = 0, k = 0, w = 0;
	unsigned int acc = 0, nbits = 0;
	size_t c, nch = sizeof(img_b64) / sizeof(img_b64[0]);

	if (!rle || !raw)
		return NULL;
	b64init();
	for (c = 0; c < nch; c++) {
		const char *p = img_b64[c];
		for (; *p; p++) {
			signed char v = b64tab[(unsigned char)*p];
			if (v < 0)
				continue;
			acc = (acc << 6) | (unsigned int)v;
			nbits += 6;
			if (nbits >= 8) {
				nbits -= 8;
				if (ro < (size_t)IMG_RLE_SIZE)
					rle[ro++] = (unsigned char)((acc >> nbits) & 0xff);
			}
		}
	}
	if (ro != (size_t)IMG_RLE_SIZE) {
		return NULL;
	}
	while (k < ro && w < (size_t)IMG_RAW_SIZE) {
		unsigned char op = rle[k++];
		if (op == 1) {
			unsigned int l = rle[k++];
			memcpy(raw + w, rle + k, l);
			k += l;
			w += l;
		} else if (op == 2) {
			unsigned int cnt = rle[k] | (rle[k + 1] << 8);
			unsigned char b = rle[k + 2];
			k += 3;
			memset(raw + w, b, cnt);
			w += cnt;
		} else {
			return NULL;
		}
	}
	if (w != (size_t)IMG_RAW_SIZE) {
		return NULL;
	}
	free(rle);
	return raw;
}

